def solve_small_n(n):
    max_x1 = 0
    # Matching
    m = n // 2
    adj = [[0] * n for _ in range(n)]
    for i in range(m):
        adj[2*i][2*i+1] = adj[2*i+1][2*i] = 1
    max_x1 = max(max_x1, count_weak_quartets(adj))

    # Complete graph K_a
    for a in range(1, n + 1):
        adj = [[0] * n for _ in range(n)]
        for i in range(a):
            for j in range(i + 1, a):
                adj[i][j] = adj[j][i] = 1
        max_x1 = max(max_x1, count_weak_quartets(adj))

    # Complete bipartite K_{a, b}
    for a in range(1, n):
        b = n - a
        adj = [[0] * n for _ in range(n)]
        for i in range(a):
            for j in range(a, n):
                adj[i][j] = adj[j][i] = 1
        max_x1 = max(max_x1, count_weak_quartets(adj))

    # Star graph K_{1, n-1}
    adj = [[0] * n for _ in range(n)]
    for i in range(1, n):
        adj[0][i] = adj[i][0] = 1
    max_x1 = max(max_x1, count_weak_quartets(adj))

