import math

def binom(n, k):
    if k < 0 or k > n:
        return 0
    return math.comb(n, k)

def solve_matching(n):
    m = n // 2
    return m * (binom(n-2, 2) - (m-1))

def solve_clique(n):
    max_val = 0
    for a in range(2, n-1):
        max_val = max(max_val, binom(a, 2) * binom(n-a, 2))
    return max_val

